function compute(inputs) {
  const f = inputs.f;
  const fs = inputs.fs;
  const fN = 2 * f;
  const k = Math.round(f / fs);
  const fa = Math.abs(f - k * fs);
  const aliased = fs < fN;
  const warning = (f <= 0 || fs <= 0) ? 'f and f_s must be positive' : null;
  // Generate time series for one period of the signal (duration = 1/f)
  const T = 1 / f;
  const N = 200;
  const t = [];
  const orig = [];
  const recon = [];
  const sampleT = [];
  const sampleY = [];
  for (let i = 0; i <= N; i++) {
    const ti = (i / N) * T;
    t.push(ti);
    orig.push(Math.sin(2 * Math.PI * f * ti));
    recon.push(Math.sin(2 * Math.PI * fa * ti));
  }
  // Sample points at multiples of 1/fs within [0, T]
  const dt = 1 / fs;
  for (let ti = 0; ti <= T + 1e-12; ti += dt) {
    sampleT.push(ti);
    sampleY.push(Math.sin(2 * Math.PI * f * ti));
  }
  const series = {
    x: t,
    lines: [
      { name: 'Original', y: orig },
      { name: 'Reconstructed', y: recon }
    ],
    marker: { x: sampleT, y: sampleY }
  };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['f (Hz)', f.toFixed(2)],
      ['f_s (Hz)', fs.toFixed(2)],
      ['Nyquist rate 2f (Hz)', fN.toFixed(2)],
      ['k = round(f/f_s)', k.toString()],
      ['Alias frequency f_a (Hz)', fa.toFixed(2)],
      ['Aliased?', aliased ? 'Yes' : 'No']
    ]
  };
  const insight = aliased
    ? `Aliasing: f_s = ${fs.toFixed(2)} Hz is below the Nyquist rate ${fN.toFixed(2)} Hz. The apparent frequency is ${fa.toFixed(2)} Hz.`
    : `No aliasing: f_s = ${fs.toFixed(2)} Hz is above the Nyquist rate ${fN.toFixed(2)} Hz. The apparent frequency equals the true frequency ${f.toFixed(2)} Hz.`;
  return {
    series: series,
    table: table,
    f: f,
    fs: fs,
    fN: fN,
    fa: fa,
    aliased: aliased,
    insight: insight,
    warning: warning
  };
}
